local gs=Players[0]:GetGovernors();
if gs:GetGovernorPoints()~=Game:GetProperty('JAC_PROXY_TOTAL_0') or gs:GetGovernorPointsSpent()~=Game:GetProperty('JAC_PROXY_SPENT_0')+1 then error('official accounting differs after 1 payments') end;
local proxy=GameInfo.Governors['GOVERNOR_JAC_TITLE_PROXY']; local native=gs:HasGovernor(proxy.Hash) and gs:GetGovernor(proxy.Hash); if not native or native:GetAssignedCity() then error('payment proxy has an assigned city or no native instance') end; for _,city in Players[0]:GetCities():Members() do if gs:CanAssignGovernor(proxy.Hash,city) then error('engine permits payment proxy assignment') end end; local total,spent=ExposedMembers.JAC_TitleProxyAccounting(0); if total~=gs:GetGovernorPoints() or spent~=gs:GetGovernorPointsSpent() then error('GameCore cannot read official accounting') end;
for stage=0,0 do if ExposedMembers.JAC_TitleProxyReceipt(0,stage)~=1 then error('native receipt absent in GameCore: '..stage) end end;
if ExposedMembers.JAC_TitleProxyReceipt(0,1)==1 then error('unpaid native stage has a receipt') end;
local q=Game:GetProperty('JAC_PROXY_PAYMENT_QUEUE_0'); if not q or q.cursor~=1 then error('persistent payment cursor differs') end;
local allocated={}; for _,r in ipairs(q.requests) do for _,stage in ipairs(r.payments) do if allocated[stage] then error('same official payment allocated twice') end; allocated[stage]=r.leader end end;
local count=0; for stage in pairs(allocated) do count=count+1 end; if count~=1 then error('allocation count differs') end;
for _,leader in ipairs({'LEADER_JAC_YAMANOUCHI_UESUGI_NORIMASA','LEADER_JAC_ODA_NOBUHIDE','LEADER_JAC_DATE_TANEMUNE'}) do
 local r=GameInfo.JAC_LeaderPersonas[leader]; local n=0; local ut=GameInfo.Units[GameInfo.GreatPersonClasses['GREAT_PERSON_CLASS_JAC_PERSONA'].UnitType];
 for _,u in Players[0]:GetUnits():Members() do if u:GetType()==ut.Index then local gp=u:GetGreatPerson(); local def=gp and GameInfo.GreatPersonIndividuals[gp:GetIndividual()]; if def and def.GreatPersonIndividualType==r.PersonType then n=n+1 end end end;
 if n~=1 then error('real Great Person fixture lost during candidate payment') end;
end;
return 'native receipt, official accounting and unique allocation verified after 1 payments'

